#!/usr/bin/env python3
from pathlib import Path
import importlib.util,sys
spec=importlib.util.spec_from_file_location("recovery_common",Path(__file__).with_name("24_1.py"));m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
FENCING_PROBE="\nimport {FileExternalFenceJournal,createExternalWriterFence,createExternalWriterObserver} from './services/hyperfide/dist/recovery/fencing.js';\nimport fs from 'node:fs/promises';\nimport {randomUUID} from 'node:crypto';\nconst root=await fs.mkdtemp('/tmp/hyperfide/fence-journal-');await fs.chmod(root,0o700);\nconst D='sha256:'+'a'.repeat(64),deployment=randomUUID(),op=randomUUID();\nconst binding={deployment_id:deployment,operation_id:op,source_epoch:null,topology_digest:D,authority_digest:D,authority_nonce:randomUUID()};\nconst resource={schema_version:1,reference_key:'constructor',operation_id:op,topology_digest:D,resource_identity_digest:D,destroy_operation:{operation_id:op},authority_digest:D,custody_evidence_digest:D,custody_expires_at:new Date(Date.now()+10000).toISOString()};\nconst outcomes={};\ntry {\n const journal=new FileExternalFenceJournal(root);\n await journal.withOperation(binding,async get=>{\n  const disk=JSON.parse(await fs.readFile(root+'/'+op+'.json','utf8'));\n  outcomes['authority-durable-before-effects']=disk.binding.authority_digest===D&&disk.binding.authority_nonce===binding.authority_nonce;\n  const slot=get('constructor');outcomes['prototype-key-is-data']=(await slot.read())===null;\n  const first=await slot.prepare(resource);outcomes['first-resource-prepared']=first.created===true&&first.state.state==='PREPARED';\n  await slot.record({binding:resource,receipt:null,observations:[]});\n });\n await journal.withOperation(binding,async get=>{\n  const slot=get('constructor'),old=await slot.prepare(resource);\n  outcomes['unknown-keeps-original-operation']=old.created===false&&old.state.state==='UNKNOWN'&&old.state.binding.destroy_operation.operation_id===op;\n  let conflict=false;try{await slot.prepare({...resource,resource_identity_digest:'sha256:'+'b'.repeat(64)})}catch(e){conflict=e.code==='EXTERNAL_FENCE_JOURNAL_CONFLICT'}\n  outcomes['resource-substitution-refused']=conflict;\n });\n let entered=false;try{await journal.withOperation({...binding,operation_id:randomUUID()},async()=>{entered=true})}catch(e){outcomes['nonce-cross-operation-refused']=e.code==='EXTERNAL_FENCE_NONCE_CONFLICT'&&!entered}\n\n const renewed={...binding,authority_digest:'sha256:'+'b'.repeat(64),authority_nonce:randomUUID()};\n await journal.withOperation(renewed,async get=>{\n  const prior=await get('constructor').read();\n  outcomes['renewal-retains-original-unknown']=prior?.state==='UNKNOWN'&&prior.binding.authority_digest===binding.authority_digest;\n });\n const retained=JSON.parse(await fs.readFile(root+'/'+op+'.json','utf8'));\n outcomes['renewed-authority-append-only']=retained.authorizations.length===2&&retained.binding.authority_digest===binding.authority_digest;\n outcomes['operation-locks-cleaned']=(await fs.readdir(root)).every(f=>!f.endsWith('.lock'));\n const hardOp=randomUUID(),hardBinding={...binding,operation_id:hardOp,authority_nonce:null};\n await journal.withOperation(hardBinding,async()=>{});\n await fs.link(root+'/'+hardOp+'.json',root+'/alias.json');\n try{await journal.withOperation(hardBinding,async()=>{})}catch(e){outcomes['hardlink-journal-refused']=e.code==='EXTERNAL_FENCE_JOURNAL_UNSAFE'}\n const config={schema_version:1,deployment_id:deployment,organisation_id:randomUUID(),run_id:randomUUID(),source_epoch:null,evidence_scope:'LIVE_PROVIDER',legacy_topology_digest:D,legacy_pid_namespace:await fs.readlink('/proc/self/ns/pid'),legacy_mount_namespace:await fs.readlink('/proc/self/ns/mnt'),required_writer_ids:['writer'],resources:[{reference_key:'writer-node',topology_digest:D,writer_ids:['writer'],backend:'PROVIDER'}]};\n let effects=0;const providers={isolateConfiguredResource:async()=>{effects++;throw new Error('unexpected external effect')}},legacy={disableAdmission:async()=>{effects++;throw new Error('unexpected legacy effect')},observeIsolation:async()=>{effects++;throw new Error('unexpected legacy observation')}};\n const authority={kind:'ISOLATION_PERMIT',permit:{}};\n try{createExternalWriterFence({...config,evidence_scope:'COMPONENT_FIXTURE'},providers,legacy,journal,authority)}catch(e){outcomes['fixture-proof-not-production']=e.code==='EXTERNAL_FENCE_EVIDENCE_SCOPE_MISMATCH'}\n try{const fence=createExternalWriterFence(config,providers,legacy,journal,authority);await fence.isolate({deployment_id:deployment,operation_id:randomUUID(),source_epoch:null})}catch(e){outcomes['unbranded-permit-refused-before-effects']=effects===0}\n try{createExternalWriterFence({...config,required_writer_ids:['writer','missing']},providers,legacy,journal,authority)}catch(e){outcomes['uncovered-writer-refused']=e.code==='EXTERNAL_FENCE_CONFIG_INCOMPLETE'}\n try{createExternalWriterFence({...config,resources:[{...config.resources[0],backend:'OWNED_HOST'}]},providers,legacy,journal,authority)}catch(e){outcomes['missing-host-backend-refused']=e.code==='EXTERNAL_FENCE_BACKEND_UNAVAILABLE'}\n\n const completeOp=randomUUID(),completeBinding={...binding,operation_id:completeOp,authority_nonce:null};\n const now=Date.now(),completeReceipt={expires_at:new Date(now+20000).toISOString(),deployment_id:deployment,operation_id:completeOp,source_epoch:null,fence_id:completeOp,isolated_writer:'topology:'+D.slice(7),observed_at:new Date(now).toISOString(),evidence_digest:D};\n await journal.withOperation(completeBinding,async(_,recordCompletion)=>{await recordCompletion(completeReceipt)});\n const retainedReceipt=await journal.readCompleted({deployment_id:deployment,operation_id:completeOp,source_epoch:null,topology_digest:D});\n outcomes['completion-exact-json-bytes-retained']=JSON.stringify(retainedReceipt)===JSON.stringify(completeReceipt);\n const savedComplete=JSON.parse(await fs.readFile(root+'/'+completeOp+'.json','utf8'));\n outcomes['completion-persisted-before-return']=savedComplete.completion_receipt_json===JSON.stringify(completeReceipt);\n try{await journal.readCompleted({deployment_id:deployment,operation_id:op,source_epoch:null,topology_digest:D})}catch(e){outcomes['missing-completion-refused']=e.code==='EXTERNAL_FENCE_COMPLETION_UNVERIFIED'}\n try{await journal.readCompleted({deployment_id:deployment,operation_id:completeOp,source_epoch:null,topology_digest:'sha256:'+'b'.repeat(64)})}catch(e){outcomes['completion-topology-substitution-refused']=e.code==='EXTERNAL_FENCE_COMPLETION_UNVERIFIED'}\n\n const obsBinding={...binding,authority_digest:'sha256:'+'c'.repeat(64),authority_nonce:randomUUID()};\n await journal.withObservation(obsBinding,async get=>{\n  const slot=get('constructor'),before=await slot.read();\n  outcomes['observation-capability-has-no-mutation-admission']=!('prepare' in slot)&&!('record' in slot);\n  const now=Date.now(),observation={reference_key:'constructor',operation_id:op,status:'UNKNOWN',observed_state:'UNKNOWN',topology_digest:D,resource_identity_digest:D,observed_at:new Date(now).toISOString(),expires_at:new Date(now+10000).toISOString(),evidence_digest:D,evidence_scope:'COMPONENT_FIXTURE',authority:'OBSERVATION_ONLY'};\n  await slot.recordObservation({binding:before.binding,observation,provider_observation:{operation:{operation_id:op},outcome:{status:'UNKNOWN'}},authorization_digest:obsBinding.authority_digest,authorization_expires_at:new Date(now+15000).toISOString()});\n  const after=await slot.read();outcomes['observation-retains-destructive-binding']=JSON.stringify(after.binding)===JSON.stringify(before.binding)&&after.state===before.state&&after.receipt===before.receipt;\n  outcomes['observation-journal-persists-only-new-read']=after.writer_observations.length===1&&after.writer_observations[0].authorization_digest===obsBinding.authority_digest;\n  try{await get('never-prepared').recordObservation({binding:before.binding,observation,provider_observation:{operation:{},outcome:{}},authorization_digest:obsBinding.authority_digest,authorization_expires_at:new Date(now+15000).toISOString()})}catch(e){outcomes['observation-cannot-prepare-new-resource']=e.code==='EXTERNAL_FENCE_OBSERVATION_UNPREPARED'}\n });\n const missingObservation={...binding,operation_id:randomUUID(),authority_nonce:randomUUID()};\n try{await journal.withObservation(missingObservation,async()=>{})}catch(e){outcomes['observation-missing-operation-no-nonce-custody']=e.code==='EXTERNAL_FENCE_OBSERVATION_UNPREPARED'&&!(await fs.readdir(root)).includes('nonce-'+missingObservation.authority_nonce+'.json')}\n let observeEffects=0;\n try{const reader=createExternalWriterObserver(config,{observeConfiguredResource:async()=>{observeEffects++;throw Error('unexpected read')}},legacy,journal);await reader.observe({},new AbortController().signal)}catch(e){outcomes['observation-unbranded-proof-refused']=observeEffects===0&&effects===0}\n console.log(JSON.stringify(outcomes));\n if(Object.keys(outcomes).length!==24||Object.values(outcomes).some(v=>v!==true))throw new Error('journal/authority regression');\n}finally{await fs.rm(root,{recursive:true,force:true})}\n"
SERVICE_PROBE="\nimport {startExternalFencingService} from './services/hyperfide/dist/recovery/fencing_service.js';\nimport {externalFenceTopologyDigest} from './services/hyperfide/dist/recovery/fencing.js';\nimport {issueIsolationPermit} from './services/hyperfide/dist/identity/credentials.js';\nimport {createIsolationHttpClient} from './services/hyperfide/dist/transport/isolation.js';\nimport {createProviderIsolation} from './services/hyperfide/dist/providers/placement.js';\nimport fs from 'node:fs/promises';import net from 'node:net';\nimport {randomUUID,generateKeyPairSync} from 'node:crypto';import {execFile} from 'node:child_process';import {promisify} from 'node:util';\nconst root=await fs.mkdtemp('/tmp/hyperfide/fencing-service-');await fs.chmod(root,0o700);\nconst outcomes={};let service;const controller=new AbortController();\ntry{\n for(const key of Object.keys(process.env))if(key==='DATABASE_URL'||key.startsWith('PG')||key==='HF_IDENTITY_CONFIG_FILE')delete process.env[key];\n const cert=root+'/cert.pem',key=root+'/key.pem';\n await promisify(execFile)('openssl',['req','-x509','-newkey','rsa:2048','-nodes','-keyout',key,'-out',cert,'-subj','/CN=127.0.0.1','-addext','subjectAltName=IP:127.0.0.1','-days','1']);await fs.chmod(key,0o600);\n const pair=generateKeyPairSync('ed25519'),signer=root+'/signer.pem',verifier=root+'/verifier.json';\n await fs.writeFile(signer,pair.privateKey.export({type:'pkcs8',format:'pem'}),{mode:0o600});\n await fs.writeFile(verifier,JSON.stringify({schema_version:1,issuers:[{key_id:'service-fixture',public_key_b64:pair.publicKey.export({type:'spki',format:'der'}).subarray(-32).toString('base64url')}]}),{mode:0o600});\n const socket=net.createServer();await new Promise((resolve,reject)=>{socket.once('error',reject);socket.listen(0,'127.0.0.1',resolve)});const port=socket.address().port;await new Promise(resolve=>socket.close(resolve));\n const D='sha256:'+'a'.repeat(64),topology={schema_version:1,deployment_id:randomUUID(),organisation_id:randomUUID(),run_id:randomUUID(),source_epoch:null,evidence_scope:'LIVE_PROVIDER',legacy_topology_digest:D,legacy_pid_namespace:await fs.readlink('/proc/self/ns/pid'),legacy_mount_namespace:await fs.readlink('/proc/self/ns/mnt'),required_writer_ids:['writer'],resources:[{reference_key:'writer-node',topology_digest:D,writer_ids:['writer'],backend:'PROVIDER'}]};\n const journal=root+'/journal';await fs.mkdir(journal,{mode:0o700});const origin='https://127.0.0.1:'+port;\n const config={schema_version:1,topology,journal_directory:journal,verifier_file:verifier,transport:{origin,host:'127.0.0.1',port,certificate:cert,private_key:key}},configFile=root+'/service.json';\n await fs.writeFile(configFile,JSON.stringify(config),{mode:0o600});\n let effects=0;const actualIsolation=createProviderIsolation({env:{},signal:controller.signal,registry:new Map()});const providers={isolateConfiguredResource:async(...args)=>{effects++;return actualIsolation(...args)}},legacy={disableAdmission:async()=>{throw new Error('No physical legacy isolation fixture configured')},observeIsolation:async()=>{throw new Error('No physical legacy isolation fixture configured')}};\n service=await startExternalFencingService({env:{HYPERFIDE_EXTERNAL_FENCE_CONFIG_FILE:configFile},signal:controller.signal,providers,legacy});\n outcomes['listener-starts-without-database']=!process.env.DATABASE_URL&&service.address===origin&&service.describe().activation_authority===false;\n const client=await createIsolationHttpClient({origin,caFile:cert,deadlineMs:3000});\n const claims=patch=>({schema_version:1,purpose:'EXTERNAL_WRITER_ISOLATION_ONLY',deployment_id:topology.deployment_id,organisation_id:topology.organisation_id,run_id:topology.run_id,operation_id:randomUUID(),source_epoch:null,topology_digest:externalFenceTopologyDigest(topology),resources:[{reference_key:'writer-node',topology_digest:D}],issued_at:new Date(Date.now()-1000).toISOString(),expires_at:new Date(Date.now()+30000).toISOString(),nonce:randomUUID(),...patch});\n async function invoke(patch){const envelope=await issueIsolationPermit(claims(patch),{key_id:'service-fixture',private_key_file:signer});return client.isolate(envelope,new AbortController().signal)}\n const wrongTopology=await invoke({topology_digest:'sha256:'+'b'.repeat(64)});\n outcomes['signed-wrong-topology-no-effects']=wrongTopology.outcome!=='SUCCEEDED'&&effects===0&&(await fs.readdir(journal)).length===0;\n const wrongResources=await invoke({resources:[{reference_key:'other-writer',topology_digest:D}]});\n outcomes['signed-wrong-resources-no-effects']=wrongResources.outcome!=='SUCCEEDED'&&effects===0&&(await fs.readdir(journal)).length===0;\n const unavailable=await invoke({});\n outcomes['unavailable-physical-backend-stays-unknown']=unavailable.outcome==='UNKNOWN'&&effects===0;\n const files=await fs.readdir(journal);outcomes['unknown-retains-durable-authority-custody']=files.some(f=>f.endsWith('.json')&&!f.startsWith('nonce-'))&&files.some(f=>f.startsWith('nonce-'))&&files.every(f=>!f.endsWith('.lock'));\n await fs.chmod(configFile,0o644);try{await startExternalFencingService({env:{HYPERFIDE_EXTERNAL_FENCE_CONFIG_FILE:configFile},signal:controller.signal,providers,legacy})}catch(e){outcomes['unsafe-server-config-refused']=e.code==='EXTERNAL_FENCE_CONFIG_UNSAFE'}await fs.chmod(configFile,0o600);\n await fs.writeFile(configFile,JSON.stringify({...config,topology:{...topology,evidence_scope:'COMPONENT_FIXTURE'}}));try{await startExternalFencingService({env:{HYPERFIDE_EXTERNAL_FENCE_CONFIG_FILE:configFile},signal:controller.signal,providers,legacy})}catch(e){outcomes['fixture-topology-cannot-start-production-listener']=e.code==='EXTERNAL_FENCE_CONFIG_INVALID'}\n await service.close();service=undefined;\n outcomes['listener-shutdown-observed']=await new Promise(resolve=>{const s=net.connect(port,'127.0.0.1');s.once('connect',()=>{s.destroy();resolve(false)});s.once('error',()=>resolve(true))});\n console.log(JSON.stringify(outcomes));if(Object.keys(outcomes).length!==8||Object.values(outcomes).some(v=>v!==true))throw new Error('Composite fencing boundary differs');\n}finally{controller.abort();await service?.close();await fs.rm(root,{recursive:true,force:true})}\n"
def fencing_tests():
 import subprocess,json
 process=subprocess.run(["node","--input-type=module"],input=FENCING_PROBE,text=True,capture_output=True,cwd=m.ROOT,timeout=30)
 m.expect(process.returncode==0,"Actual fencing journal probe failed: "+process.stderr[-400:])
 for key,value in json.loads(process.stdout).items():m.check("recovery.fence."+key,lambda value=value:m.expect(value is True))
 process=subprocess.run(["node","--input-type=module"],input=SERVICE_PROBE,text=True,capture_output=True,cwd=m.ROOT,timeout=30)
 m.expect(process.returncode==0,"Actual composite listener probe failed: "+process.stderr[-400:])
 for key,value in json.loads(process.stdout).items():m.check("recovery.fencing-service."+key,lambda value=value:m.expect(value is True))
def tests(f):
 fencing_tests()
 m.check("recovery.stop.real-process",lambda:m.expect(f.ok("recovery.stop.describe",{})["unreachable_means"]=="DEBT"))
 request={"scope":m.SCOPE,"operation_id":m.uid(50),"scope_kind":"RUN","scope_id":m.RUN,"mode":"STOP","reason":"component fixture stop"}
 result=f.ok("recovery.stop.request",request)
 m.check("recovery.stop.durable-control",lambda:m.expect(m.sql("SELECT mode||':'||status FROM hyperfide.recovery_controls;")=="STOP:ACTIVE"))
 m.check("recovery.stop.revoke-before-external-call",lambda:m.expect(m.sql("SELECT state FROM hyperfide.compute_leases;")=="REVOKED"))
 m.check("recovery.stop.run-stopping",lambda:m.expect(m.sql("SELECT state FROM hyperfide.runs WHERE id='"+m.RUN+"';")=="STOPPING"))
 m.check("recovery.stop.worker-and-leader-debt",lambda:m.expect(m.sql("SELECT count(*) FROM hyperfide.recovery_resource_debts;")=="2"))
 m.check("recovery.stop.custody-explicitly-revoked",lambda:m.expect(m.sql("SELECT authority FROM hyperfide.submission_custodies;")=="REVOKED"))
 m.check("recovery.stop.qualification-lease-fenced",lambda:m.expect(m.sql("SELECT state||':'||lease_generation FROM hyperfide.qualification_jobs;")=="CANCELLED:2"))
 m.check("recovery.stop.not-falsely-complete",lambda:m.expect(result["process_stop_complete"] is False and result["cleanup_complete"] is False))
 m.check("recovery.stop.idempotent-command",lambda:m.expect(f.ok("recovery.stop.request",request)==result))
 m.check("recovery.stop.enclosing-control-precedence",lambda:f.rejected("recovery.stop.request",{**request,"operation_id":m.uid(51),"scope_kind":"ATTEMPT","scope_id":m.ATTEMPT,"mode":"PAUSE"},"RECOVERY_ENCLOSING_CONTROL"))
 m.check("recovery.stop.unknown-supervisor-refuses",lambda:f.rejected("recovery.stop.reconcile",{"scope":m.SCOPE,"operation_id":m.uid(50)},"RECOVERY_DEPENDENCY_UNAVAILABLE"))
 m.check("recovery.stop.debt-survives-restart",lambda:m.expect(m.sql("SELECT count(*) FROM hyperfide.recovery_resource_debts WHERE status='OPEN';")=="2"))
 m.check("recovery.stop.finalize-unproven-cleanup",lambda:f.rejected("recovery.stop.finalize",{"scope":m.SCOPE,"operation_id":m.uid(50)},"RECOVERY_DEPENDENCY_UNAVAILABLE"))
 m.check("recovery.stop.reject-caller-confirmation",lambda:f.rejected("recovery.stop.reconcile",{"scope":m.SCOPE,"operation_id":m.uid(50),"stopped":True},"RECOVERY_INPUT_INVALID"))
 m.check("recovery.stop.cross-run-scope",lambda:f.rejected("recovery.stop.request",{**request,"operation_id":m.uid(52),"scope_id":m.uid(80)},"RECOVERY_SCOPE_INVALID"))
 m.check("recovery.stop.stale-epoch",lambda:f.rejected("recovery.stop.request",{**request,"operation_id":m.uid(53),"scope":{**m.SCOPE,"authority_epoch":m.uid(98)}},"RECOVERY_STALE_EPOCH"))
 # A historical sandbox still owes physical cleanup; it cannot own a task handed to another sandbox.
 m.sql("INSERT INTO hyperfide.sandboxes(organisation_id,id,pool_id,observed_state) VALUES('"+m.ORG+"','"+m.uid(70)+"','"+m.uid(8)+"','RUNNING');")
 m.sql("INSERT INTO hyperfide.worker_slots(organisation_id,id,sandbox_id,slot_key,boot_generation,capacity_kind) VALUES('"+m.ORG+"','"+m.uid(71)+"','"+m.uid(70)+"','replacement',1,'AGENT');")
 m.sql("INSERT INTO hyperfide.attempts(organisation_id,run_id,id,task_id,generation,authority_epoch,input_packet_digest,execution_state,compute_authority,sandbox_id,slot_id,sandbox_boot_generation) VALUES('"+m.ORG+"','"+m.RUN+"','"+m.uid(72)+"','"+m.uid(7)+"',2,'"+m.EPOCH+"','"+m.D+"','SUBMITTED','RELEASED','"+m.uid(70)+"','"+m.uid(71)+"',1);")
 m.sql("UPDATE hyperfide.tasks SET current_attempt_id='"+m.uid(72)+"',generation=2,state='SUBMITTED',state_version=state_version+1 WHERE id='"+m.uid(7)+"';")
 m.sql("INSERT INTO hyperfide.submission_custodies(organisation_id,run_id,id,task_id,source_attempt_id,source_generation,custody_generation,authority_epoch,repository_id,source_object_id,source_manifest_digest,evidence_manifest_digest,criteria_digest) SELECT organisation_id,run_id,'"+m.uid(73)+"','"+m.uid(7)+"','"+m.uid(72)+"',2,1,authority_epoch,repository_id,source_object_id,source_manifest_digest,evidence_manifest_digest,criteria_digest FROM hyperfide.submission_custodies WHERE id='"+m.uid(24)+"';")
 old=f.ok("recovery.stop.request",{**request,"operation_id":m.uid(74),"scope_kind":"SANDBOX","scope_id":m.uid(9)})
 m.check("recovery.stop.historical-sandbox-excludes-new-task",lambda:m.expect(m.uid(7) not in old["affected_task_ids"]))
 m.check("recovery.stop.historical-sandbox-preserves-new-task",lambda:m.expect(m.sql("SELECT state FROM hyperfide.tasks WHERE id='"+m.uid(7)+"';")=="SUBMITTED"))
 m.check("recovery.stop.historical-sandbox-preserves-new-custody",lambda:m.expect(m.sql("SELECT authority FROM hyperfide.submission_custodies WHERE id='"+m.uid(73)+"';")=="ACTIVE"))
 m.check("recovery.stop.historical-sandbox-preserves-new-attempt",lambda:m.expect(m.sql("SELECT compute_authority||':'||execution_state FROM hyperfide.attempts WHERE id='"+m.uid(72)+"';")=="RELEASED:SUBMITTED"))
 m.check("recovery.stop.historical-sandbox-retains-physical-debt",lambda:m.expect(m.sql("SELECT count(*) FROM hyperfide.recovery_resource_debts WHERE operation_id='"+m.uid(74)+"' AND resource_id='"+m.uid(22)+"';")=="1"))
 m.sql("INSERT INTO hyperfide.tasks(organisation_id,run_id,id,task_key,feature_package_id,spec_revision_id,criteria_digest,definition,wave) VALUES('"+m.ORG+"','"+m.RUN+"','"+m.uid(75)+"','1.3','"+m.uid(6)+"','"+m.uid(4)+"','"+m.D+"','{}',1);")
 whole=f.ok("recovery.stop.request",{**request,"operation_id":m.uid(76)})
 m.check("recovery.stop.run-includes-unattempted-task",lambda:m.expect(m.uid(75) in whole["affected_task_ids"]))
 m.check("recovery.stop.unattempted-task-admission-blocked",lambda:m.expect(m.sql("SELECT state FROM hyperfide.tasks WHERE id='"+m.uid(75)+"';")=="BLOCKED"))
if __name__=="__main__":sys.exit(m.run("24.3",tests))
